UPDATE SVC_SRVC_INFO_TBL 
SET 		SRVC_CD	= 	(
					CASE
						WHEN (#{srvcCd, jdbcType=VARCHAR} IS NULL OR #{srvcCd, jdbcType=VARCHAR} = '') THEN SRVC_CD
						ELSE #{srvcCd, jdbcType=VARCHAR}
					END
			)
		  , SRVC_TP = (
					CASE
						WHEN (#{srvcTp, jdbcType=VARCHAR} IS NULL OR #{srvcTp, jdbcType=VARCHAR} = '') THEN SRVC_TP
						ELSE #{srvcTp, jdbcType=VARCHAR}
					END
		    )
		  , USE_YN = (
					CASE
						WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
						ELSE #{useYn, jdbcType=VARCHAR}
					END
		    )
		  , SRVC_NM = (
					CASE
						WHEN (#{srvcNm, jdbcType=VARCHAR} IS NULL OR #{srvcNm, jdbcType=VARCHAR} = '') THEN SRVC_NM
						ELSE #{srvcNm, jdbcType=VARCHAR}
					END
		    )
		  , SRVC_BSC_URI = (
					CASE
						WHEN (#{srvcBscUri, jdbcType=VARCHAR} IS NULL OR #{srvcBscUri, jdbcType=VARCHAR} = '') THEN SRVC_BSC_URI
						ELSE #{srvcBscUri, jdbcType=VARCHAR}
					END
		    )
		  , SRVC_DESC = (
					CASE
						WHEN (#{srvcDesc, jdbcType=VARCHAR} IS NULL OR #{srvcDesc, jdbcType=VARCHAR} = '') THEN SRVC_DESC
						ELSE #{srvcDesc, jdbcType=VARCHAR}
					END
		    )
		  , UPDT_DT = CURRENT_TIMESTAMP(3)
		  , UPDT_SEQ = (
					CASE
						WHEN (#{updtSeq, jdbcType=NUMERIC} IS NULL OR #{updtSeq, jdbcType=NUMERIC} = 0) THEN UPDT_SEQ
						ELSE #{updtSeq, jdbcType=NUMERIC}
					END						
		    )
WHERE 	1 	= 	1
AND 		(((#{srvcSeq, jdbcType=NUMERIC} IS NULL) OR (#{srvcSeq, jdbcType=NUMERIC} = 0)) OR (SRVC_SEQ = #{srvcSeq, jdbcType=NUMERIC}))
